If you're using ngnix as a reverse proxy on you server you should have `proxy_buffering off;` in your config and increase `proxy_read_timeout` so that responses don't timeout when streaming.

```nginx
...

server {
    listen       443 ssl http2;
    listen       [::]:443 ssl http2;
    server_name example.com;

    ssl_certificate /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    location / {
        proxy_pass http://localhost:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        proxy_buffering off; # <--- must be off
        proxy_read_timeout 300s; # <--- shouldn't be a low number
    }

    location /static/ {
        alias /path/to/static/files/;
        expires 7d;
        add_header Cache-Control "public";
    }
}

...
```

