createGoogleGenerativeAI({
      apiKey: this.apiKey,
      fetch: async (url, options) => {
        const body = JSON.parse(options.body);
        let tools: undefined | object;
        if ('tools' in body) {
          tools = [{ codeExecution: {} }];
        }
        const sendBody = JSON.stringify({
          ...body,
          tools,
        });
        return fetch(url, {
          ...options,
          body: sendBody,
