Resolved. Here's what I found for anyone who comes across the same issue.

Langfuse queues traces, but serverless functions terminate quickly, leaving the background Langfuse agent insufficient time to send events before exiting. See [here](https://langfuse.com/docs/tracing#queuing-batching)

The solution is to do manual flushing as suggested [here](https://langfuse.com/faq/all/aws-lambda-and-serverless-functions)

```ts
import { LangChainAdapter, Message } from 'ai';
import { CallbackHandler } from "langfuse-langchain";
import { ChatOpenAI } from "@langchain/openai";
import { waitUntil } from "@vercel/functions";  // ADD

const model = new ChatOpenAI({
    model: 'gpt-4o-mini',
    temperature: 0,
});

const langfuseHandler = new CallbackHandler({
    publicKey: process.env.LANGFUSE_PUBLIC_KEY,
    secretKey: process.env.LANGFUSE_SECRET_KEY,
    baseUrl: process.env.LANGFUSE_BASE_URL,
});

export async function POST(req: Request) {
    const { messages }: { messages: Message[] } = await req.json();

    const stream = await model.stream(
        messages,
        { callbacks: [langfuseHandler] }
    );
    
    waitUntil(langfuseHandler.flushAsync());  // ADD

    return LangChainAdapter.toDataStreamResponse(stream);
}

```

