            dataStream.writeMessageAnnotation({
              id: generateId(),
              finishReason: event.finishReason,
              isContinued: event.isContinued,
              stepType: event.stepType,
              text: event.text,
              toolCalls: event.toolCalls,
              toolResults: event.toolResults,
            });
          },
        });

