```typescript 
import { createAmazonBedrock } from "@ai-sdk/amazon-bedrock";
import { fromNodeProviderChain } from "@aws-sdk/credential-providers";

export const bedrock = createAmazonBedrock({
  region: process.env.AWS_REGION,
  credentialProvider: fromNodeProviderChain(),
});

// AWS Bedrock Cohere embedding options
export interface CohereEmbeddingOptions {
  truncate?: "NONE" | "START" | "END";
  embeddingTypes?: ("float" | "int8" | "uint8" | "binary" | "ubinary")[];
  modelId?: string;
  region?: string;
  inputType?:
    | "search_document"
    | "search_query"
    | "classification"
    | "clustering"
    | "image";
}

export interface CohereEmbeddingResponse {
  embeddings: {
    float?: number[][];
    int8?: number[][];
    uint8?: number[][];
    binary?: number[][];
    ubinary?: number[][];
  };
  id: string;
  response_type: string;
  texts?: string[];
  images?: Array<{
    width: number;
    height: number;
    format: string;
    bit_depth: number;
  }>;
}

interface CohereRequestBody {
  input_type:
    | "search_document"
    | "search_query"
    | "classification"
    | "clustering"
    | "image";
  texts?: string[];
  images?: string[];
  truncate?: "NONE" | "START" | "END";
  embedding_types?: ("float" | "int8" | "uint8" | "binary" | "ubinary")[];
}

/**
 * @param inputs - text array or base64 data uri 
 * @param options - cohere embed api option
 * @returns embeddings array
 *
 * @example
 * ```typescript
 * // text embeddings
 * const textEmbeddings = await createCohereEmbeddings(
 *   ["Hello world", "How are you?"],
 *   { inputType: "text" }
 * );
 *
 * // image embeddings
 * const imageDataUri = "data:image/jpeg;base64,/9j/4AAQSkZJRgABAQ...";
 * const imageEmbeddings = await createCohereEmbeddings(
 *   [imageDataUri],
 *   { inputType: "image" }
 * );
 * ```
 */
export const createCohereEmbeddings = async (
  inputs: string[],
  options: CohereEmbeddingOptions = {},
): Promise<number[][]> => {
  const {
    truncate = "NONE",
    embeddingTypes = ["float"],
    modelId = "cohere.embed-multilingual-v3",
    region = process.env.AWS_REGION,
    inputType = "search_document",
  } = options;

  if (inputs.length === 0) {
    throw new Error("inputs array cannot be empty");
  }

  if (inputType === "image") {
    if (inputs.length > 1) {
      throw new Error("Maximum 1 image is allowed per call");
    }

    // validate data uri 
    for (const dataUri of inputs) {
      if (!dataUri.startsWith("data:image/")) {
        throw new Error(
          "Invalid image data URI format. Must start with 'data:image/'",
        );
      }

      const [header] = dataUri.split(",");
      if (!header.includes("base64")) {
        throw new Error("Image data URI must be base64 encoded");
      }
    }
  }

  try {
    const { BedrockRuntimeClient, InvokeModelCommand } = await import(
      "@aws-sdk/client-bedrock-runtime"
    );
    const { fromNodeProviderChain } = await import(
      "@aws-sdk/credential-providers"
    );

    const client = new BedrockRuntimeClient({
      region,
      credentials: fromNodeProviderChain(),
    });

    // follow aws bedrock api 
    const requestBody: CohereRequestBody = {
      input_type: inputType,
    };

    if (inputType === "image") {
      requestBody.images = inputs;
    } else {
      requestBody.texts = inputs;
    }

    // option parameter 
    if (truncate !== "NONE") {
      requestBody.truncate = truncate;
    }

    if (embeddingTypes.length > 0) {
      requestBody.embedding_types = embeddingTypes;
    }

    console.log("Cohere request body:", JSON.stringify(requestBody, null, 2));

    const command = new InvokeModelCommand({
      modelId,
      body: JSON.stringify(requestBody),
      contentType: "application/json",
      accept: "*/*",
    });

    const response = await client.send(command);

    if (!response.body) {
      throw new Error("No response body received from Bedrock");
    }

    const responseBody: CohereEmbeddingResponse = JSON.parse(
      new TextDecoder().decode(response.body),
    );

    const primaryType = embeddingTypes[0];
    return (
      responseBody.embeddings[primaryType] ||
      responseBody.embeddings.float ||
      []
    );
  } catch (error) {
    console.error("Error creating Cohere embeddings:", error);
    console.error("Full error details:", error);

    if (error && typeof error === "object") {
      if ("$metadata" in error) {
        console.error("AWS metadata:", error.$metadata);
      }
      if ("__type" in error) {
        console.error("Error type:", error.__type);
      }
    }

    throw error;
  }
};


// Custom Cohere embedding function for text (used for queries)
export const cohereEmbedMultilingual = {
  specificationVersion: "v1" as const,
  provider: "bedrock" as const,
  modelId: "cohere.embed-multilingual-v3",
  maxEmbeddingsPerCall: 1, // Cohere has limits
  supportsParallelCalls: false,

  doEmbed: async (options: { values: string[] }) => {
    const embeddings: number[][] = [];
    // Process one by one since Cohere has limits
    for (const value of options.values) {
      const result = await createCohereEmbeddings([value], {
        inputType: "search_query",
        modelId: "cohere.embed-multilingual-v3",
      });
      embeddings.push(result[0]);
    }
    return {
      embeddings,
      usage: {
        tokens: options.values.reduce((sum, value) => sum + value.length, 0),
      },
    };
  },
};

// Custom Cohere embedding function for images (used for storing image embeddings)
export const cohereEmbedMultilingualImage = {
  specificationVersion: "v1" as const,
